17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	import java.util.UUID;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!normalizeNewOwner(owner)) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (dailyLimitReached(owner.getRegistrationDate())) {
116	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
117	        }
118	        if (cityIsAtCapacity(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (emailAlreadyUsed(owner.getEmail())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        Optional<Owner> householdMember = findHouseholdMember(owner);
128	        if (householdMember.isPresent()) {
129	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
130	                return new ResponseEntity<>(HttpStatus.CONFLICT);
131	            }
132	            joinHousehold(owner, householdMember.get());
133	        }
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
135	        owner.setNamesakeCount(countNamesakes(owner));
136	        owner.setMembershipNumber(membershipNumber(owner));
137	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
138	        owner.setHouseholdSize(householdSize(owner));
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
160	        String email = ownerFieldsDto.getEmail();
161	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
217	        HttpHeaders headers = new HttpHeaders();
218	        Visit visit = visitMapper.toVisit(visitFieldsDto);
219	        Pet pet = new Pet();
220	        pet.setId(petId);
221	        visit.setPet(pet);
222	        this.clinicService.saveVisit(visit);
223	        VisitDto visitDto = visitMapper.toVisitDto(visit);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
225	            .buildAndExpand(visit.getId()).toUri());
226	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
227	    }
228	
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner != null) {
235	            Pet pet = owner.getPet(petId);
236	            if (pet != null) {
237	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    /**
244	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
245	     * the canonical form each stored value must take: the address is trimmed,
246	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
247	     * telephone is converted to E.164, any email is lower-cased and a missing
248	     * registration date defaults to today. Field-level rejections are reported here
249	     * rather than inline in {@link #addOwner}, and normalisation runs before any
250	     * household comparison so those comparisons see the canonical values.
251	     *
252	     * @param owner the freshly-mapped owner to normalise
253	     * @return {@code true} if the fields are valid, or {@code false} if the address
254	     *         is blank after normalisation or the telephone cannot form a valid
255	     *         E.164 number, in which case the request must be rejected with
256	     *         {@code 400 Bad Request}
257	     */
258	    private boolean normalizeNewOwner(Owner owner) {
259	        String address = Owner.normalizeAddress(owner.getAddress());
260	        if (address.isEmpty()) {
261	            return false;
262	        }
263	        owner.setAddress(address);
264	        String telephone = toE164(owner.getTelephone());
265	        if (telephone == null) {
266	            return false;
267	        }
268	        owner.setTelephone(telephone);
269	        if (owner.getEmail() != null) {
270	            owner.setEmail(owner.getEmail().toLowerCase());
271	        }
272	        if (owner.getRegistrationDate() == null) {
273	            owner.setRegistrationDate(LocalDate.now());
274	        }
275	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
276	        return true;
277	    }
278	
279	    /**
280	     * Roll the given date forward to the next business day when it falls on a
281	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
282	     * weekday is returned unchanged. Applied to the effective registration date
283	     * (whether supplied in the request or defaulted to the server date) so that
284	     * every value derived from it uses the adjusted business day.
285	     *
286	     * @param date the effective registration date
287	     * @return the same date if it is a weekday, otherwise the next Monday
288	     */
289	    private static LocalDate rollToBusinessDay(LocalDate date) {
290	        switch (date.getDayOfWeek()) {
291	            case SATURDAY:
292	                return date.plusDays(2);
293	            case SUNDAY:
294	                return date.plusDays(1);
295	            default:
296	                return date;
297	        }
298	    }
299	
300	    /**
301	     * Determine whether the given (already lower-cased) email is already used by any
302	     * existing owner, compared on the lower-cased email value. Owners without an email
303	     * never match, so a {@code null} or blank candidate email is never a duplicate.
304	     *
305	     * @param email the candidate owner's normalised (lower-cased) email
306	     * @return {@code true} if an existing owner already uses that email
307	     */
308	    private boolean emailAlreadyUsed(String email) {
309	        if (email == null || email.isBlank()) {
310	            return false;
311	        }
312	        return this.clinicService.findAllOwners().stream()
313	            .map(Owner::getEmail)
314	            .filter(existing -> existing != null)
315	            .anyMatch(existing -> existing.toLowerCase().equals(email));
316	    }
317	
318	    /**
319	     * Find an existing owner that belongs to the same household as the given owner,
320	     * i.e. shares the same last name and address (compared case-insensitively with
321	     * runs of whitespace collapsed to a single space).
322	     *
323	     * @param owner the candidate owner being created
324	     * @return the matching existing owner, or empty if none exists
325	     */
326	    private Optional<Owner> findHouseholdMember(Owner owner) {
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> existing.sameHouseholdAs(owner))
329	            .findFirst();
330	    }
331	
332	    /**
333	     * Assign the joining owner and an existing household member the same stable
334	     * household identifier. The identifier is derived deterministically from the
335	     * shared household key (last name + address, normalised), so every owner in a
336	     * household resolves to the same value; the existing member is updated when it
337	     * does not already carry it.
338	     *
339	     * @param owner    the owner being created
340	     * @param existing an existing owner in the same household
341	     */
342	    private void joinHousehold(Owner owner, Owner existing) {
343	        String householdId = UUID
344	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
345	        owner.setHouseholdId(householdId);
346	        if (!householdId.equals(existing.getHouseholdId())) {
347	            existing.setHouseholdId(householdId);
348	            this.clinicService.saveOwner(existing);
349	        }
350	    }
351	
352	    /**
353	     * Count how many owners belong to the given owner's household once this create
354	     * completes: the owners that already share its {@code householdId} plus the owner
355	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
356	     * so the household identifier (and any existing member updated to it) is already in
357	     * place. An owner that has not joined a household (no {@code householdId}) is a
358	     * household of one.
359	     *
360	     * @param owner the candidate owner being created, after household resolution
361	     * @return the household member count after this create (at least {@code 1})
362	     */
363	    private int householdSize(Owner owner) {
364	        String householdId = owner.getHouseholdId();
365	        if (householdId == null) {
366	            return 1;
367	        }
368	        long existing = this.clinicService.findAllOwners().stream()
369	            .filter(other -> householdId.equals(other.getHouseholdId()))
370	            .count();
371	        return (int) existing + 1;
372	    }
373	
374	    /**
375	     * Count the existing owners that share the given owner's first and last name,
376	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
377	     * before the new owner is saved, so the result reflects only owners that
378	     * already existed at creation time.
379	     *
380	     * @param owner the candidate owner being created
381	     * @return the number of existing namesakes
382	     */
383	    private int countNamesakes(Owner owner) {
384	        String firstName = normalizeName(owner.getFirstName());
385	        String lastName = normalizeName(owner.getLastName());
386	        return (int) this.clinicService.findAllOwners().stream()
387	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
388	                && normalizeName(existing.getLastName()).equals(lastName))
389	            .count();
390	    }
391	
392	    private static String normalizeName(String value) {
393	        return value == null ? "" : value.trim().toLowerCase();
394	    }
395	
396	    /**
397	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
398	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
399	     * first three letters of the given last name and NNNN a per-city 4-digit
400	     * zero-padded sequence equal to one more than the number of owners already in
401	     * that city (e.g. {@code SYD-SMI-0007}).
402	     *
403	     * @param city     the owner's city
404	     * @param lastName the owner's last name
405	     * @return the assigned customer code
406	     */
407	    /**
408	     * Determine whether the given city has already reached its owner capacity, i.e.
409	     * it already contains 50 or more existing owners (compared case-insensitively
410	     * with surrounding whitespace trimmed). A new owner may not be created in a city
411	     * that is at capacity.
412	     *
413	     * @param city the candidate owner's city
414	     * @return {@code true} if the city already holds 50 or more owners
415	     */
416	    private boolean cityIsAtCapacity(String city) {
417	        String normalizedCity = normalizeName(city);
418	        long count = this.clinicService.findAllOwners().stream()
419	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
420	            .count();
421	        return count >= 50;
422	    }
423	
424	    /**
425	     * Determine whether the daily owner-creation limit has already been reached, i.e.
426	     * 100 or more owners already carry the given registration date. A new owner may
427	     * not be created once that day's cap is reached.
428	     *
429	     * @param registrationDate the registration date the new owner would be created with
430	     * @return {@code true} if 100 or more existing owners share that registration date
431	     */
432	    private boolean dailyLimitReached(LocalDate registrationDate) {
433	        long count = this.clinicService.findAllOwners().stream()
434	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
435	            .count();
436	        return count >= 100;
437	    }
438	
439	    /**
440	     * Determine whether more than 80 owners have already been created for the given
441	     * registration date, i.e. strictly more than 80 existing owners carry that date.
442	     * Evaluated before the new owner is saved, so it reflects only owners that
443	     * already existed at creation time.
444	     *
445	     * @param registrationDate the registration date the new owner would be created with
446	     * @return {@code true} if more than 80 existing owners share that registration date
447	     */
448	    private boolean bulkSignupWarning(LocalDate registrationDate) {
449	        long count = this.clinicService.findAllOwners().stream()
450	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
451	            .count();
452	        return count > 80;
453	    }
454	
455	    private String nextCustomerCode(String city, String lastName) {
456	        String city3 = prefix3(city);
457	        String last3 = prefix3(lastName);
458	        long sequence = this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
460	            .count() + 1L;
461	        return String.format("%s-%s-%04d", city3, last3, sequence);
462	    }
463	
464	    private static String prefix3(String value) {
465	        String v = value == null ? "" : value;
466	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
467	    }
468	
469	    /**
470	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
471	     * where {@code <customerCode>} is the owner's already-assigned customer code and
472	     * YY is the last two digits of the registration date's year (e.g.
473	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
474	     * have been set.
475	     *
476	     * @param owner the owner being created, with customer code and registration date
477	     *              already assigned
478	     * @return the assigned membership number
479	     */
480	    private String membershipNumber(Owner owner) {
481	        int yy = owner.getRegistrationDate().getYear() % 100;
482	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
483	    }
484	
485	    /**
486	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
487	     * code when present, otherwise assume country code '+61' and drop a single
488	     * leading '0' from the national digits. Spaces, dashes and brackets are
489	     * stripped. The result must contain 8 to 15 digits after the '+'.
490	     *
491	     * <p>In addition, the national-number length is validated against the country
492	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
493	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
494	     * whose national-number length is wrong for its country code is rejected.
495	     *
496	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
497	     *         input cannot form a valid E.164 number.
498	     */
499	    private static String toE164(String raw) {
500	        if (raw == null) {
501	            return null;
502	        }
503	        String cleaned = raw.replaceAll("[\\s()-]", "");
504	        String digits;
505	        if (cleaned.startsWith("+")) {
506	            digits = cleaned.substring(1);
507	        } else {
508	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
509	            digits = "61" + national;
510	        }
511	        if (!digits.matches("\\d{8,15}")) {
512	            return null;
513	        }
514	        if (!nationalNumberLengthValid(digits)) {
515	            return null;
516	        }
517	        return "+" + digits;
518	    }
519	
520	    /**
521	     * Validate the length of the national number (the digits after the country
522	     * code) against the country code carried by the given E.164 digit string: a
523	     * {@code 61} (Australia) number requires exactly 9 national digits and a
524	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
525	     * without a pinned length are accepted (only the generic 8-15 digit rule
526	     * applies to them).
527	     *
528	     * @param digits the E.164 digits without the leading '+'
529	     * @return {@code true} if the national-number length is correct for the country
530	     */
531	    private static boolean nationalNumberLengthValid(String digits) {
532	        if (digits.startsWith("61")) {
533	            return digits.length() - 2 == 9;
534	        }
535	        if (digits.startsWith("1")) {
536	            return digits.length() - 1 == 10;
537	        }
538	        return true;
539	    }
540	}
